    strings.sort((a, b) -> b.length() - a.length());

    for (String str: strings) {
        for (int i = 0; i < str.length(); i++) {
            int start = i;
            StringBuilder reversedStr = new StringBuilder();
            while (start >= 0 && !Character.isDigit(str.charAt(start))) {
