public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
        }

        return dfs(0, -1, graph, hasApple);
    }

private int dfs(int current, int parent, Map<Integer, List<Integer>> graph, boolean[] hasApple) {
        int totalTime = 0;

        // Check if the current node has an apple
        if (hasApple[current]) totalTime += 2;

        // Recur for each child node
        for (int child : graph.getOrDefault(current, new ArrayList<>())) {
            if (child != parent) {
                totalTime += dfs(child, current, graph, hasApple);
            }
        }

        return totalTime;
    }

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    // Build maxHeap
    for (char c : s.toCharArray()) {
        maxHeap.offer(c);
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        // Extract the smallest character from minHeap
        char minChar = minHeap.isEmpty() ? maxHeap.poll() : minHeap.poll();
        result.append(minChar);

        // Ensure the smallest character is not processed again
        while (!minHeap.isEmpty() && minHeap.peek() == minChar) {
            minHeap.poll();
        }

        // Extract the largest character from maxHeap
        char maxChar = maxHeap.isEmpty() ? minHeap.poll() : maxHeap.poll();
        result.append(maxChar);

        // Ensure the largest character is not processed again
        while (!maxHeap.isEmpty() && maxHeap.peek() == maxChar) {
            maxHeap.poll();
        }
    }

    return result.toString();
}

