public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    Stack<Character> stack = new Stack<>();
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else {
            if (!stack.isEmpty()) {
                stack.pop();
            } else {
                insertions++;
            }
        }
    }

    insertions += stack.size() * 2;

    return insertions;
}

public int minOperations(int n) {
