        throw new IllegalArgumentException("Input must be a positive integer");
    }
    int totalSum = n * (2 * n - 1);
    int average = totalSum / n;
    int totalOperations = 0;
    for (int i = 0; i < n; i++) {
        int current = (2 * i) + 1;
        totalOperations += Math.abs(current - average);
    }
    return totalOperations / 2;
}

