    }

    int maxSum = nums[0];
    int minSum = nums[0];
    int maxAbsoluteSum = nums[0];

    for (int i = 1; i < nums.length; i++) {
        if (nums[i] > 0) {
            maxSum += nums[i];
            minSum = Math.min(minSum + nums[i], nums[i]);
        } else {
            maxSum = Math.max(maxSum + nums[i], nums[i]);
            minSum = Math.min(minSum + nums[i], nums[i]);
        }
        maxAbsoluteSum = Math.max(maxAbsoluteSum, Math.max(maxSum, -minSum));
    }
