}

public int findMinFibonacciNumbers(int k) {
    ArrayList<Integer> fib = new ArrayList<>();
    int i = 1, j = 1;
    fib.add(i);
    fib.add(j);
    int next = fib.get(i) + fib.get(j);
    while (next <= k) {
        fib.add(next);
        i = j;
        j = next;
        next = fib.get(i) + fib.get(j);
    }

    int result = 0;
    while (k > 0) {
        result++;
        int index = bisectRight(fib, k);
        k -= fib.get(index);
    }

    return result;
}

public int bisectRight(ArrayList<Integer> arr, int x) {
    int low = 0, high = arr.size() - 1;
    while (low <= high) {
        int mid = low + ((high - low) / 2);
        if (arr.get(mid) == x) {
            return mid;
        } else if (arr.get(mid) < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
}

