public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    // Special cases for low and high
    if (low == 0) result.add(low);
    if (high < 0) return result;
    if (high >= 10) high = 9; // Upper bound can maximum be 9

    // Start with single digits
    for (int i = 0; i <= 9; i++) {
        deepSearch(result, i, low, high);
    }

    return result;
}

private static void deepSearch(List<Integer> result, int current, int low, int high) {
    if (current >= low && current <= high) {
        result.add(current);
    }

    // Generate next possible numbers
    for (int i = -1; i <= 1; i++) {
        int next = current * 10 + (current + i);
        if (next >= low && next <= high) {
            deepSearch(result, next, low, high);
        }
    }
}

public static int countDigitOne(int n) {
