        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    int count = 0;
    int k = 1;
    while (n >= k) {
        int digit = n / k % 10;
        int offset = n % k;

        count += (digit == 1) ? offset + 1 : k;

        k *= 10;
    }

    return count;
}

