    if (n <= 0) {
        return false; // Non-positive integers cannot be powers of two
    }
    for (int i = 0; (1 << i) <= n; i++) {
        if ((1 << i) == n) {
            return true;
        }
    }
    return false;
}

public static int addDigits(int num) {
    while (num >= 10) {
        num = sumDigits(num);
    }
    return num;
}

private static int sumDigits(int number) {
    int sum = 0;
    while (number > 0) {
        sum += number % 10;
        number /= 10;
    }
    return sum;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        throw new IllegalArgumentException("The input matrix cannot be null or empty");
    }

    int maxLength = 0;
    int[][] directions = {
        {0, 1}, {1, 1}, {1, 0}, {0, -1}
    };

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, longestLineRecursive(mat, i, j, directions));
            }
        }
    }

    return maxLength;
}

public static int longestLineRecursive(int[][] mat, int i, int j, int[][] directions) {
    int count = 1;
    for (int[] direction : directions) {
        int ti = i + direction[0], tj = j + direction[1];
        while (ti >= 0 && ti < mat.length && tj >= 0 && tj < mat[0].length && mat[ti][tj] == 1) {
            ti += direction[0];
            tj += direction[1];
            count++;
        }
    }
    return count;
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";

    String neg = "";
    if (n < 0) {
        neg = "-";
        n = Math.abs(n);
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
