    while (i < digits.length) {
        if (i != 0 && i % 3 == 0) sb.append(".");
        sb.append(digits[i++]);
    }

    return n < 0 ? "-" + sb.toString() : sb.toString();
}

public static int squarePermutations(int[] A) {
    int len = A.length;
    if (len == 0) return 0;

    // Sort the array to potentially simplify the search
    Arrays.sort(A);

    // Initialize the count of square permutations
    int count = 0;

    // Iterate through the array to form permutations
    for (int i = 0; i < len - 1; i++) {
        if (A[i] > A[i + 1] || A[i] * A[i] % 10 != 0) {
            // Skip dupe elements and invalid combinations
            continue;
        }
        int j = i + 1;
        while (j < len && A[j] * A[j] % 10 != 0) {
            j++;
        }
        // Skip repeat combinations
        if (j < len && A[j] == A[i]) {
            continue;
        }

        // Recursive permutation generation
        boolean[] visited = new boolean[len];
        Helper(A, i, j, visited, 0, count);
    }

    return count;
}

private static void Helper(int[] A, int i, int j, boolean[] visited, int perm, int[] count) {
    if (perm == visited.length) {
        count[0]++;
        return;
    }

    for (int k = i + 1; k < j; k++) {
        if (visited[k] || (k > i + 1 && !visited[k - 1] && A[k - 1] > A[k])) continue;

        visited[k] = true;
        Helper(A, i, j, visited, perm + 1, count);
        visited[k] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];

    // Find the nearest smaller element to the left of each element
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack
    stack.clear();

    // Find the nearest smaller element to the right of each element
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = n;
        } else {
            rightSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (rightSmaller[i] - leftSmaller[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int x = 0, y = 0;

    // Traverse the diagonals in a zigzag pattern
    while (index < m * n) {
        result[index++] = mat[x][y];
        if (x == 0 && y < n - 1) {
            y++;
        } else if (y == n - 1 && x < m - 1) {
            x++;
        } else if (x < m - 1 && y == 0) {
            x++;
        } else if (x == m - 1 && y < n - 1) {
            x--;
            y++;
        } else {
            x--;
            y--;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 1) {
        return -1; // No positive integer greater than 1 can be formed by rearranging its digits.
    }

    // Convert the integer to a character array.
    char[] digits = String.valueOf(n).toCharArray();

    // Bubble sort the digits in descending order.
    for (int i = 0; i < digits.length; i++) {
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[i] < digits[j]) {
                // Swap the digits.
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
            }
        }
    }

    // Check if the resulting string can be converted back to an integer.
    // If not, return -1.
    try {
        int smallestNumber = Integer.parseInt(new String(digits));
        // Check if the smallest number is greater than the input number.
        if (smallestNumber > n) {
            return smallestNumber;
        }
    } catch (NumberFormatException e) {
        return -1; // Invalid number format, return -1.
    }

    // Return -1 if no valid rearrangements can form a number greater than the input number.
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        if (n % 2 == 0 && i >= n / 2) {
            centerSymmetricNumbers.add(getSymmetry(i));
        } else if (n % 2 != 0 && i >= (n - 1) / 2) {
            centerSymmetricNumbers.add(getSymmetry(i));
        }
    }
    return centerSymmetricNumbers;
}

private static String getSymmetry(int i) {
    String left = getMirror(i);
    String right = getMirror(i);
    return left + right;
}

private static String getMirror(int i) {
    StringBuilder mirror = new StringBuilder();
    for (int j = i; j >= 0; j--) {
        mirror.append(i - j);
    }
    return mirror.toString();
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Exactly 3 points are required");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if any point is the same as any other point
    if (x1 == x2 || x1 == x3 || y1 == y2 || y1 == y3) {
        return false;
    }

    // Check if the points form a non-degenerate triangle (area formula not needed, but to avoid division by zero)
    // If the points are on the same line, there will be side length of 0
    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);
    double slope3 = (y1 - y3) / (x1 - x3);

    return !Math.abs(slope1 - slope2) <= 1e-9 && !Math.abs(slope2 - slope3) <= 1e-9;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    if (DP[n][3] > 0) {
        return DP[n][3];
    }

    int i0 = 0, i1 = 0, i2 = 0;
    int indices[] = {i0, i1, i2};
    int[] nums = {2, 3, 5};

    for (int i = 1; i <= n; i++) {
        int nouvelleValeur = Math.min(nums[0], Math.min(nums[1], nums[2]));
        DP[i][0] = DP[i-1][0] + (DP[i][3] == 0 ? 1 : 0);
        DP[i][1] = nouvelleValeur;
        indices[nums.indexOf(nouvelleValeur)]++;
        nums[nums.indexOf(nouvelleValeur)] *= 2;
    }

    return DP[n][1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxLength = 0;
    int currentLength = 1;
    Character currentChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
            currentChar = s.charAt(i);
        }
    }

    maxLength = Math.max(maxLength, currentLength);
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result; // Return an empty list for non-positive input
    }

    // Create a priority queue to maintain the numbers in lexicographical order
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    // Initialize the queue with the smallest number
    queue.offer(1);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        result.add(current); // Add the current number to the result list

        // Check if the current number can be multiplied by and added to (10 * current) to get a new number within the range
        if (current * 10 <= n) {
            queue.offer(current * 10); // Add the new number to the queue
        }

        // Check if the current number can be incremented by 1 to get a new number within the range
        if (current + 1 <= n) {
            queue.offer(current + 1); // Add the new number to the queue
        }
    }

    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int limit = (int) Math.sqrt(n);
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= limit; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty.");
    }

    String[] words = s.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        StringBuilder reversedWord = new StringBuilder(words[i]);
        int left = 0, right = reversedWord.length() - 1;
        while (left < right) {
            char temp = reversedWord.charAt(left);
            reversedWord.setCharAt(left, reversedWord.charAt(right));
            reversedWord.setCharAt(right, temp);
            left++;
            right--;
        }
        words[i] = reversedWord.toString();
    }

    return String.join(" ", words);
}
